\begin{tikzpicture}[font=\sffamily, >=Stealth, line width=0.8pt]
% axes
\draw[->] (0,0) -- (0,6) node[midway, left=4pt, rotate=90, anchor=south] {energy};
\draw[->] (0,0) -- (8.4,0) node[midway, below=6pt] {progress of reaction};
% uncatalysed curve
\draw (0.5,3) -- (1.8,3) .. controls (2.8,3) and (2.7,5) .. (3.5,5) .. controls (4.3,5) and (4.5,1) .. (5.5,1) -- (7.6,1);
% catalysed curve
\draw[dashed] (1.8,3) .. controls (2.6,3) and (2.7,4) .. (3.5,4) .. controls (4.3,4) and (4.5,1) .. (5.5,1);
% Ea
\draw[dotted, gray] (1.0,5) -- (3.5,5);
\draw[<->] (1.0,3) -- (1.0,5) node[midway, left=3pt] {$E_\mathrm{a}$};
% Delta H
\draw[dotted, gray] (4.5,3) -- (7.0,3);
\draw[->] (7.0,3) -- (7.0,1) node[midway, right=3pt] {$\Delta H$};
% labels
\node[anchor=north] at (1.2,2.85) {reactants};
\node[anchor=north] at (6.6,0.85) {products};
\node[anchor=west] at (6.0,4.6) {without catalyst};
\draw[-{Stealth[length=2mm]}, line width=0.5pt] (5.95,4.6) -- (4.1,4.1);
\node[anchor=north] at (3.0,2.2) {with catalyst};
\draw[-{Stealth[length=2mm]}, line width=0.5pt] (3.0,2.25) -- (3.0,3.6);
% caption
\node at (4.2,-1.2) {Fig. 4.1};
\end{tikzpicture}
